from lib import *
recs=[]
recs.append(R(6482949,"گرِل کی ہوئی اسٹرابیری \"کریم\" پر بالسامک گلیز کے ساتھ","بالسامک گلیز کے ساتھ \"کریم\" پر گرِل کی ہوئی اسٹرابیری کی یہ ذیابیطس کے لیے موزوں ترکیب یقیناً سب کو متاثر کرے گی! میپل سیرپ یا شہد جیسے قدرتی میٹھے استعمال کرنے سے اضافی غذائی اجزاء ملتے ہیں۔ یونانی دہی اضافی پروٹین فراہم کرتا ہے جو اس مزیدار میٹھے کو کھانے کے بعد آپ کو سیری کا احساس دلاتا ہے۔ اگر آپ گلوٹین فری یا سبزی خور میٹھے کی تلاش میں ہیں تو یہ بھی ایک بہترین انتخاب ہے۔","2","½ پلیٹ (9 اسٹرابیری کے آدھے ٹکڑے + 1/3 کپ کریم)",
["2/3 کپ سادہ بغیر چکنائی والا یونانی دہی","1 کھانے کا چمچ لائٹ کریم چیز (کمرے کے درجہ حرارت پر)","1/2 چائے کا چمچ شہد","9 بڑی اسٹرابیریاں (ڈنٹھل ہٹائے ہوئے، آدھی کٹی ہوئی)","2 چائے کے چمچ سورج مکھی یا ایوکاڈو کا تیل","1 کھانے کا چمچ بالسامک گلیز یا بالسامک ریڈکشن ساس*","2 چائے کے چمچ کٹے ہوئے بادام (پین میں بھنے ہوئے یا کچے)","1 کھانے کا چمچ بہت چھوٹے تازہ تلسی یا پودینے کے پتے"],
["ایک درمیانے پیالے میں دہی، نوفشاتل پنیر اور شہد کو گاڑھا اور کریمی ہونے تک پھینٹ لیں۔ کریم کو سرونگ پلیٹر یا بورڈ پر پھیلا دیں۔","گرِل یا گرِل پین تیار کر کے پہلے سے گرم کریں۔ اسٹرابیری کے آدھے ٹکڑوں کی کٹی ہوئی طرف تیل لگائیں اور براہ راست درمیانی تیز آنچ پر کٹی طرف نیچے رکھ کر گرِل کریں، جب تک گہرے گرِل کے نشان نہ بن جائیں، تقریباً 4 منٹ۔","اسٹرابیریوں کو کریم کے اوپر سجا دیں۔ بالسامک گلیز ڈالیں، بادام اور تازہ جڑی بوٹیاں چھڑکیں اور پیش کریں۔","*اپنی بالسامک ریڈکشن ساس خود بنائیں: ایک چھوٹے ساس پین میں 1/4 کپ بالسامک سرکہ ڈالیں، تیز آنچ پر اُبال لائیں، پھر آنچ کو درمیانی کر دیں اور کبھی کبھار ہلاتے ہوئے اتنا پکائیں کہ وہ چمچ کی پشت پر بس چڑھنے لگے (تقریباً 1 1/2 کھانے کے چمچ حاصل ہوں گے)، تقریباً 5 منٹ۔ (نوٹ: بالسامک ریڈکشن ٹھنڈا ہونے پر ذرا مزید گاڑھا ہو جاتا ہے۔)"]))
recs.append(R(6483037,"گرِل کی ہوئی مکئی لال مرچ اور لائم کے ساتھ","اس گرِل کی ہوئی مکئی لال مرچ اور لائم کے ساتھ ٹیکس-میکس انداز کا لطف اٹھائیں۔ میکسیکن اسٹریٹ کارن جیسے ذائقے والی یہ ذیابیطس کے لیے موزوں ترکیب لذیذ اور غذائیت بخش ہے۔","4","مکئی کا 1 بھٹا",
["1 کپ تازہ ہرا دھنیا (کٹا ہوا، سجاوٹ کے لیے)","1/4 کپ پارٹ اسکم موزاریلا (سجاوٹ کے لیے)","1/8 چائے کا چمچ نمک","1 درمیانا لائم (چھلکا اور رس)","1/2 چائے کا چمچ اسموکڈ پیپریکا","1 چائے کا چمچ لال مرچ پاؤڈر (چلی پاؤڈر)","1 عدد نان اسٹک کوکنگ اسپرے","4 درمیانے مکئی کے بھٹے (چھلکے اتارے ہوئے)"],
["گرِل کو درمیانی تیز آنچ پر پہلے سے گرم کریں۔","ایک چھوٹے پیالے میں زیتون کا تیل، لال مرچ پاؤڈر، اسموکڈ پیپریکا، لائم کا چھلکا، لائم کا رس اور نمک ملا کر پھینٹ لیں۔","مکئی کے بھٹوں پر یہ میرینیڈ لگائیں اور یقینی بنائیں کہ ہر طرف برابر لگ جائے۔","مکئی کو کم از کم 30 منٹ تک میرینیٹ ہونے دیں۔","میرینیٹ کی ہوئی مکئی کو پہلے سے گرم گرِل پر رکھیں۔ تقریباً 15 منٹ تک گرِل کریں، وقفے وقفے سے پلٹتے رہیں، جب تک مکئی ہلکی جل نہ جائے اور اندر تک پک نہ جائے۔","گرِل کی ہوئی مکئی کو آنچ سے اتار لیں۔","مکئی کو سرونگ پلیٹر میں منتقل کریں اور اس پر کوتیا پنیر اور تازہ کٹا ہوا ہرا دھنیا چھڑکیں۔"]))
recs.append(R(6483274,"شیٹ پین پر زکینی اور لال شملہ مرچ کا \"اسٹر فرائی\"","یہ ترکیب دیکھنے اور چکھنے میں اسٹر فرائی جیسی ہے، لیکن اسے چولھے پر پکانے کے بجائے اوون میں روسٹ کیا جاتا ہے۔ بس سب کچھ ملائیں، شیٹ پین پر پھیلائیں اور بیک ہونے دیں! یہ ایسے ہی بہترین ہے، یا آپ اضافی ذائقے ڈال سکتے ہیں: کرکراہٹ کے لیے مونگ پھلی چھڑکیں؛ تیزی کے لیے ہاٹ ساس ڈالیں؛ اور جڑی بوٹیوں کے ذائقے کے لیے تازہ ہرا دھنیا ملائیں۔","4","1 1/2 کپ",
["2 درمیانی لال شملہ مرچیں (1 انچ کی پٹیوں میں کٹی ہوئی)","2 درمیانی زکینی (1/2 موٹے گول ٹکڑوں میں کٹی ہوئی)","1 1/2 کھانے کے چمچ بھنے ہوئے تل کا تیل","1 1/2 کھانے کے چمچ رائس سرکہ","2 کھانے کے چمچ اور 2 چائے کے چمچ کم سوڈیم والی سویا ساس","1 کھانے کا چمچ تازہ ادرک (کدوکش کیا ہوا)","1 (14 اونس) پیکٹ ایکسٹرا فرم ٹوفو"],
["اوون کو 450°F پر پہلے سے گرم کریں۔ ایک بڑی کناروں والی بیکنگ شیٹ پر بغیر بلیچ والا پارچمنٹ پیپر بچھا دیں۔","اگر ضروری ہو تو ٹوفو کو تھپتھپا کر یا دبا کر زائد پانی نکال دیں۔ ٹوفو کو (3/4 انچ کے) چکور ٹکڑوں میں کاٹ لیں۔","ایک بڑے پیالے میں ادرک، تماری، سرکہ اور تیل کو پھینٹ لیں۔ زکینی اور شملہ مرچ کے ٹکڑے ساس کے مرکب میں ڈالیں؛ ہاتھ سے ملائیں تاکہ سب پر لگ جائے۔","زکینی اور مرچوں کو بیکنگ شیٹ پر ایک تہہ میں سجائیں (شیٹ کا 2/3 حصہ بھریں)، اور زائد ساس کو واپس پیالے میں ٹپکنے دیں۔","ٹوفو کو بچی ہوئی ساس کے مرکب والے پیالے میں ڈالیں؛ ملا لیں تاکہ سب پر لگ جائے۔ ٹوفو کو بیکنگ شیٹ پر ایک تہہ میں سجائیں (شیٹ کا باقی حصہ بھریں)۔ ٹوفو پر بچی ہوئی ساس ڈال دیں۔","ٹوفو اور سبزیوں کے بھورا ہونے تک روسٹ کریں، تقریباً 30 منٹ؛ ہلانے کی ضرورت نہیں۔ پیش کریں۔"]))
recs.append(R(6485584,"ہرے مرچ والا چکن کیسرول","یہ ہرے مرچ والا چکن کیسرول سب کو پسند آنے والی ڈش ہے، اور ہری مرچوں، چکن اور پنیر کا امتزاج ایک پرسکون اور مزیدار ڈش بناتا ہے۔ یہ ہفتے کی کسی عام رات کے آسان کھانے کے لیے بہترین ہے جسے پورا خاندان پسند کرے گا۔","8","تقریباً 1/2 کپ",
["1 اسپرے نان اسٹک کوکنگ اسپرے","2 کپ پکا ہوا چکن (بریسٹ، ریشہ ریشہ کیا ہوا)","1 (15 اونس) ڈبہ کالی پھلیاں (بغیر نمک اضافے کے، دھوئی ہوئی اور پانی نکالی ہوئی)","1 (4 اونس) ڈبہ بند ہری مرچیں (پانی نکالی ہوئی)","2 درمیانی لال شملہ مرچیں","1 کپ سادہ بغیر چکنائی والا یونانی دہی","1/3 کپ سالسا ورڈے (ٹماٹیو سالسا)","1 چائے کا چمچ پسا ہوا زیرہ","1/2 چائے کا چمچ لہسن پاؤڈر","1/4 چائے کا چمچ کالی مرچ","3/4 کپ کدوکش کیا ہوا میکسیکن پنیر کا مرکب (کم چکنائی والا)","1 کھانے کا چمچ تازہ ہرا دھنیا (کٹا ہوا، سجاوٹ کے لیے)"],
["اوون کو 375 ڈگری F پر پہلے سے گرم کریں۔ 9 انچ کی چکور بیکنگ ڈش پر کوکنگ اسپرے کریں۔","ایک بڑے پیالے میں کٹا ہوا چکن، کالی پھلیاں، کٹی ہوئی ہری مرچیں، لال شملہ مرچ، یونانی دہی، سالسا ورڈے، پسا ہوا زیرہ، لہسن پاؤڈر اور کالی مرچ ملائیں۔ اچھی طرح ملنے تک مکس کریں۔","چکن کا مرکب بیکنگ ڈش میں چمچ سے ڈالیں اور برابر پھیلا دیں۔","اوپر کدوکش کیا ہوا چیڈر پنیر چھڑکیں۔","کیسرول کو فوائل سے ڈھانپ کر 25 منٹ بیک کریں۔","فوائل ہٹا دیں اور کیسرول کے گرم ہو کر بلبلے اٹھنے اور پنیر کے پگھل کر سنہری بھورا ہونے تک بیک کریں، تقریباً 10 منٹ مزید۔","اوون سے نکالیں اور 8 چکور ٹکڑوں میں کاٹنے سے پہلے چند منٹ ٹھنڈا ہونے دیں۔ اوپر کٹا ہوا تازہ ہرا دھنیا ڈالیں۔"]))
recs.append(R(6486814,"اسموکی مشروم","پکے ہوئے مشروم برگر یا اسٹیک کے لذیذ ذائقے کو بڑھا دیتے ہیں۔ یہ روسٹ کیے ہوئے پورک لوئن یا گرِل کیے ہوئے ٹوفو کے ساتھ بھی بہترین سائیڈ ڈش ہیں۔ اس ترکیب میں آپ سفید، کریمینی (بیبی بیلا)، شیٹاکے یا اوئسٹر مشروم، یا مختلف اقسام کا مرکب استعمال کر سکتے ہیں۔ اگر آپ شیٹاکے مشروم استعمال کر رہے ہیں تو پورا ڈنٹھل نکال کر پھینک دیں۔","5","1/2 کپ",
["1/2 چائے کا چمچ کوشر نمک","1 کھانے کا چمچ بھنے ہوئے تل کا تیل","1 1/2 کھانے کے چمچ لکوئڈ اسموک","2 1/2 کھانے کے چمچ زیتون کا تیل","1 1/2 پاؤنڈ سفید (بٹن) مشروم","1 عدد پارچمنٹ پیپر"],
["اوون کو 350°F پر پہلے سے گرم کریں۔ دو بیکنگ شیٹس پر پارچمنٹ پیپر بچھا دیں؛ ایک طرف رکھ دیں۔","سفید مشروم کے ڈنٹھل کاٹ دیں۔ مشروم کو 3/8 انچ موٹے ٹکڑوں میں کاٹ لیں۔ مشروم کو ایک پیالے میں ڈالیں۔ باقی اجزاء ڈال کر اچھی طرح ملا لیں۔ مرکب خشک نظر آئے گا۔","مشروم کو ہر شیٹ پر ایک تہہ میں پھیلا دیں۔ 10 منٹ روسٹ کریں۔ مشروم کے ٹکڑے پلٹیں اور مزید 10 منٹ روسٹ کریں۔","آنچ کو 375°F تک بڑھا دیں اور 15 منٹ روسٹ کریں۔ مشروم کے ٹکڑے ایک بار پھر پلٹیں اور مزید 10 منٹ روسٹ کرتے رہیں۔ سائیڈ ڈش کے طور پر پیش کریں، یا سینڈوچ، آملیٹ اور سوپ میں ڈالیں۔"]))
recs.append(R(6487257,"شکر قندی اور پالک کے ڈمپلنگز","لذیذ شکر قندی کے ڈمپلنگز گوشت والی ٹماٹر ساس میں گھرے ہوئے ہیں، ریسٹورنٹ کے معیار کی اس مین ڈش میں۔","8","3 ڈمپلنگز، 1/4 کپ ساس",
["1 بڑی شکر قندی","1 بڑا انڈا","2 بڑے انڈوں کی سفیدی","1 کپ بغیر چکنائی اور کم سوڈیم والا ریکوٹا پنیر","2 کھانے کے چمچ پارمیزان پنیر (کدوکش کیا ہوا)","1/4 چائے کا چمچ کالی مرچ","1/4 چائے کا چمچ پسی ہوئی جائفل","1/2 کپ منجمد پالک (کٹی ہوئی، پگھلائی ہوئی اور پانی نچوڑا ہوا)","1 کپ سفید سالم گندم کا آٹا","1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے","1 پاؤنڈ کم چکنائی والا ٹرکی کا قیمہ (98% چکنائی سے پاک)","1 عدد مرینارا ساس (24.5 اونس کی بوتل، کم سوڈیم والی (جیسے Amy’s))","1 کپ چکن یا سبزیوں کا شوربہ (کم سوڈیم)"],
["اوون کو 375 ڈگری F پر پہلے سے گرم کریں۔ شکر قندی کو بیکنگ شیٹ پر رکھیں اور 40 منٹ بیک کریں، یا جب تک کانٹے سے چھیدنے پر نرم نہ ہو جائے۔ شکر قندی کو اوون سے نکال کر ٹھنڈا ہونے کے لیے ایک طرف رکھ دیں۔","اس دوران ایک بڑے پیالے میں انڈا، انڈوں کی سفیدی اور کاٹیج چیز کو ہموار ہونے تک پھینٹ لیں۔ پارمیزان پنیر، کالی مرچ، جائفل اور پالک آہستگی سے ملا دیں۔","شکر قندی کا چھلکا اتار کر اچھی طرح مسل لیں۔ مسلی ہوئی شکر قندی اور آٹا انڈے اور پنیر کے مرکب میں آہستگی سے ملا دیں۔ مرکب گیلا اور چپچپا ہوگا۔ اسے 10 منٹ آرام کرنے دیں۔","جب آٹا آرام کر رہا ہو، ایک بڑے سوتے پین یا ڈچ اوون پر کوکنگ اسپرے لگائیں اور اسے درمیانی تیز آنچ پر گرم کریں۔ ٹرکی ڈالیں اور بمشکل پکنے تک سوتے کریں، تقریباً 8 منٹ۔","ٹرکی پر مرینارا ساس اور شوربہ ڈالیں اور ہلا کر ملا دیں۔ آنچ کو کم کر دیں۔","ڈمپلنگ کے آمیزے کے 2 انچ کے گولے اٹھا کر آہستگی سے ساس میں ڈالتے جائیں تاکہ 24 ڈمپلنگز بن جائیں۔ ڈھانپ کر 20 منٹ ہلکی آنچ پر پکائیں۔"]))
recs.append(R(6487300,"لال پیاز والی ہری پھلیاں","تازہ ہری پھلیاں، جو بس چند منٹ پکائی جاتی ہیں، نازک کرکراہٹ اور خوشگوار ذائقہ رکھتی ہیں۔ تازہ تھائم اور سوتے کی ہوئی لال پیاز کے ساتھ یہ سائیڈ ڈش آپ کی پسندیدہ بن جائے گی۔","8","1 کپ",
["1/2 چائے کا چمچ سمندری نمک","2 پاؤنڈ تازہ ہری پھلیاں (سرے کٹے ہوئے)","5 چائے کے چمچ لائٹ مکھن نما اسپریڈ","2 کھانے کے چمچ زیتون کا تیل","2 درمیانی لال پیاز (آدھی کٹی ہوئی، چھلی ہوئی، اور 1/2 انچ موٹے قتلوں میں کٹی ہوئی)","1 کھانے کا چمچ تازہ تھائم (باریک کٹا ہوا)","1/2 کپ کٹے ہوئے بادام","1 کھانے کا چمچ لیموں کا چھلکا (1 درمیانے لیموں سے)"],
["6 کوارٹ کے برتن میں 2/3 حصہ پانی بھر کر ابالیں۔ نمک ڈالیں۔ ہری پھلیاں ڈالیں اور آنچ بند کر دیں۔ ہری پھلیوں کو 3 سے 4 منٹ پانی میں پڑا رہنے دیں۔ پانی نتھار لیں۔ ہری پھلیوں کو برف کے پانی کے پیالے میں ڈبو دیں۔ پھلیوں کا پانی نتھار کر ایک طرف رکھ دیں۔","ایک بڑے فرائنگ پین میں مکھن اور تیل درمیانی آنچ پر گرم کریں۔ پیاز ڈالیں اور کبھی کبھار ہلاتے ہوئے 20 سے 25 منٹ تک پکائیں، جب تک بہت نرم نہ ہو جائے۔ اگر پیاز بہت جلدی بھورا ہونے لگے تو آنچ کم کر دیں۔","پیاز میں تھائم اور ہری پھلیاں ڈالیں اور چمٹے سے سبزیوں کو آہستگی سے پلٹتے ہوئے گرم کریں۔ پیش کرنے کے لیے پیاز اور ہری پھلیوں کا مرکب تھال میں رکھیں اور اوپر بادام اور لیموں کا چھلکا ڈالیں۔"]))
recs.append(R(6488181,"جھینگا سیویچے","سیویچے کی اس قسم میں لذیذ جھینگے، میٹھا انناس اور تیز مرچیں کھٹے لائم میرینیڈ میں شامل ہیں۔ اسے پکے ہوئے چاول اور مٹر کے اوپر، یا پکی ہوئی مچھلی پر سالسا کے طور پر پیش کریں۔ یا کریکرز کے ساتھ ناشتے یا اسٹارٹر کے طور پر پیش کریں۔","6","1/2 کپ",
["1 کھانے کا چمچ زیتون کا تیل","1 چائے کا چمچ لہسن پاؤڈر","2 کھانے کے چمچ سفید سرکہ","3 کھانے کے چمچ لائم کا رس","2 کھانے کے چمچ تازہ ہرا دھنیا","1 کپ کٹا ہوا انناس","1 چھوٹی تیز مرچ (موٹی کٹی ہوئی)","1 پیلی بنانا پیپر (موٹی کٹی ہوئی)","1 درمیانا ٹماٹر (موٹا کٹا ہوا)","2 ہری پیاز (موٹی کٹی ہوئی)","12 جھینگے (منجمد، پکے ہوئے اور چھلے ہوئے)"],
["مرکب کو ایک سرونگ پیالے میں ڈالیں اور اس میں کٹے ہوئے جھینگے اور زیتون کا تیل ملا دیں۔ پیش کرنے سے پہلے 30 منٹ یا زیادہ دیر تک ٹھنڈا کریں۔","فوڈ پروسیسر میں ہری پیاز، ٹماٹر، مرچیں، انناس اور ہرا دھنیا ڈالیں؛ آن-آف بٹن سے پلس کر کے بہت موٹا کٹ لیں۔ ٹکڑوں والی ساخت مطلوب ہے۔ مرکب میں لائم کا رس، سرکہ اور لہسن پاؤڈر ڈالیں۔"]))
recs.append(R(6488782,"کیل اور سیب کا کول سلا","آپ اس کول سلا میں سبزیاں بدل سکتے ہیں، جیسے کٹی ہوئی پالک، ہری بند گوبھی اور کدوکش کی ہوئی گاجر استعمال کریں۔\n\nاپنی پلیٹ مکمل کریں: اس سبزی کی سائیڈ ڈش کو Easy Beef Chili کے ساتھ پیش کریں۔ دونوں بچ جانے پر بھی بہترین رہتے ہیں، اس لیے یہ پہلے سے تیاری کے کھانے کے لیے بہت اچھا ہے۔","4","1 1/4 کپ",
["1/2 کپ سادہ بغیر چکنائی والا یونانی دہی","1 جوا لہسن (باریک کٹا ہوا)","1 چائے کا چمچ ڈیجون رائی","1 کھانے کا چمچ زیتون کا تیل","3 کھانے کے چمچ لیموں کا رس","3 کھانے کے چمچ پانی","1/4 چائے کا چمچ نمک","1/8 چائے کا چمچ کالی مرچ","2 کپ کٹی ہوئی کیل","3 کپ کدوکش کی ہوئی لال بند گوبھی","1 فوجی سیب (چھلکے سمیت کدوکش کیا ہوا)"],
["ایک بڑے پیالے میں دہی، لہسن، رائی، زیتون کا تیل، لیموں کا رس، پانی، نمک اور کالی مرچ کو پھینٹ لیں۔","کیل، بند گوبھی اور سیب پیالے میں ڈالیں اور برابر لگنے تک ملا لیں۔ ڈھانپ کر پیش کرنے سے 30 منٹ پہلے فریج میں رکھ دیں تاکہ ذائقے آپس میں مل جائیں۔"]))
recs.append(R(6489390,"تقریباً ہموار سالسا","کیا آپ ہموار سالسا پسند کرتے ہیں یا ٹکڑوں والی؟ اگر آپ کو ہموار سالسا پسند ہے تو ہموار ہونے تک بلینڈ کریں۔ اگر ٹکڑوں والی پسند ہے تو بلینڈ کرنا بالکل چھوڑ دیں۔","12","2 کھانے کے چمچ",
["2 درمیانے روما (پلم) ٹماٹر (چکور کٹے ہوئے)","1/4 درمیانی ہری شملہ مرچ (چکور کٹی ہوئی)","1/4 درمیانی لال پیاز (چکور کٹی ہوئی)","1/2 عدد ہالاپینو مرچ (بیج اور رگیں نکلی ہوئی، چکور کٹی ہوئی)","3 کھانے کے چمچ تازہ ہرا دھنیا (کٹا ہوا)","1 کھانے کا چمچ لائم کا رس","1 کھانے کا چمچ زیتون کا تیل","1/4 چائے کا چمچ نمک","1/8 چائے کا چمچ کالی مرچ"],
["ٹماٹر، شملہ مرچ، پیاز، ہالاپینو اور ہرا دھنیا ایک درمیانے پیالے میں ڈالیں۔ لائم کا رس، زیتون کا تیل، نمک اور کالی مرچ ڈالیں۔ برابر لگنے تک ملا لیں۔","ایمرشن بلینڈر سے تقریباً ہموار ہونے تک بلینڈ کریں، اور سالسا میں کچھ ٹکڑے رہنے دیں۔"]))
recs.append(R(6489812,"پارسلے اور ہرے دھنیے کی چمچوری والی بیکڈ کاڈ مچھلی","پارسلے، ہرے دھنیے، سرکے اور لائم سے بنی چٹپٹی چمچوری ساس ہلکے ذائقے والی کاڈ مچھلی پر ڈالی جاتی ہے۔ یہ ذیابیطس کے لیے موزوں پروٹین ڈش جلدی تیار ہو جاتی ہے اور اوون میں بیک کر کے آسانی سے بنتی ہے۔ اس کے ساتھ مزیدار نشاستے والی سائیڈ کے طور پر ہرے دھنیے اور لائم والا کینوا بنانے کی کوشش کریں۔","4","1 کاڈ + 2 کھانے کے چمچ ساس",
["4 (4 اونس) فلیٹ کاڈ فلیٹس","4 جوے لہسن","1/2 درمیانی لال پیاز (کٹی ہوئی)","1 کپ تازہ چپٹے پتوں والا پارسلے (دبا کر بھرا ہوا)","1 کپ تازہ ہرے دھنیے کے پتے (دبا کر بھرے ہوئے)","1/4 چائے کا چمچ کٹی ہوئی لال مرچ کے فلیکس","1/8 چائے کا چمچ کالی مرچ","2 کھانے کے چمچ ریڈ وائن سرکہ","1 چائے کا چمچ لائم کا چھلکا","2 کھانے کے چمچ تازہ لائم کا رس","4 کھانے کے چمچ زیتون کا تیل (تقسیم کر کے استعمال کریں)"],
["اوون کو 400°F پر پہلے سے گرم کریں۔","کاڈ فلیٹس کو پارچمنٹ پیپر بچھی بیکنگ شیٹ پر رکھیں۔ ان پر 1 کھانے کا چمچ تیل ہلکا سا ڈالیں۔ بیکنگ شیٹ اوون میں رکھیں اور اس وقت تک پکائیں جب تک مچھلی کا اندرونی درجہ حرارت 145°F نہ ہو جائے، 8–10 منٹ۔","لہسن، پیاز، پارسلے، ہرا دھنیا، کٹی ہوئی لال مرچ اور کالی مرچ فوڈ پروسیسر میں ڈالیں۔ باریک کٹنے تک پروسیس کریں۔","سرکہ، لائم کا چھلکا اور رس، اور 3 کھانے کے چمچ زیتون کا تیل ڈالیں۔ ہموار ہونے تک پروسیس کریں اور ایک طرف رکھ دیں۔","پیش کرنے کے لیے مچھلی کو پلیٹوں میں تقسیم کریں اور اوپر چمچوری ساس ڈالیں۔"]))
